const design = readFileSync(resolve(process.cwd(), "../../docs/design/frontend/DESIGN.md"), "utf8");
const css = readFileSync(resolve(process.cwd(), "src/foundations/oac.css"), "utf8");

const colorNames = [
  "primary",
  "white",
  "canvas",
  "surface",
  "surfaceSubtle",
  "surfaceRaised",
  "ink",
