  "canvasDark",
  "surfaceDark",
  "surfaceRaisedDark",
  "inkDark",
  "inkSecondaryDark",
  "dividerDark",
  "actionDark",
] as const;

function kebabCase(value: string) {
  return value.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);
}

describe("OAC design foundations", () => {
  it("uses the color tokens declared by DESIGN.md as its single authority", () => {
    for (const colorName of colorNames) {
      const designValue = design.match(new RegExp(`${colorName}: "(#[0-9A-F]{6})"`))?.[1];
      expect(designValue, `${colorName} must exist in DESIGN.md`).toBeDefined();
      expect(css).toContain(`--oac-color-${kebabCase(colorName)}: ${designValue};`);
    }
  });
});
