{"content":[{"type":"text","text":"import type { ButtonHTMLAttributes } from "react";

export type ButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  isLoading?: boolean;
  variant?: "action" | "danger" | "quiet";
};

export function Button({
  children,
  className,
  disabled,
  isLoading = false,
  type = "button",
  variant = "action",
  ...properties
}: ButtonProps) {
  const classes = ["oac-ui-button", `oac-ui-button--${variant}`, className].filter(Boolean).join(" ");

  return (
    <button
      {...properties}
      aria-busy={isLoading || undefined}
      className={classes}
      disabled={disabled || isLoading}
      type={type}
    >
      {children}
    </button>
  );
}
import { useId, type InputHTMLAttributes } from "react";

export type TextInputProps = Omit<InputHTMLAttributes<HTMLInputElement>, "id"> & {
  description?: string;
  error?: string;
  id?: string;
  label: string;
};

export function TextInput({
  "aria-describedby": suppliedDescriptionIds,
  "aria-invalid": suppliedInvalid,
  className,
  description,
  error,
  id,
  label,
  ...properties
}: TextInputProps) {
  const generatedId = useId();
  const inputId = id ?? generatedId;
  const descriptionId = description === undefined ? undefined : `${inputId}-description`;
  const errorId = error === undefined ? undefined : `${inputId}-error`;
  const describedBy = [suppliedDescriptionIds, descriptionId, errorId].filter(Boolean).join(" ") || undefined;

  return (
    <div className="oac-ui-field">
      <label className="oac-ui-field__label" htmlFor={inputId}>{label}</label>
      <input {...properties} aria-describedby={describedBy} aria-invalid={error !== undefined || suppliedInvalid} className={["oac-ui-input", className].filter(Boolean).join(" ")} id={inputId} />
      {description === undefined ? null : <span id={descriptionId}>{description}</span>}
      {error === undefined ? null : <span id={errorId} role="alert">{error}</span>}
    </div>
  );
}
import { useRef, type KeyboardEvent } from "react";

export type UiLocale = "en-US" | "zh-CN";

export type LanguageSegmentedControlProps = {
  label?: string;
  onChange: (locale: UiLocale) => void;
  value: UiLocale;
};

const choices: ReadonlyArray<{ label: string; value: UiLocale }> = [
  { label: "中文", value: "zh-CN" },
  { label: "English", value: "en-US" },
];

export function LanguageSegmentedControl({ label = "Language", onChange, value }: LanguageSegmentedControlProps) {
  const choiceReferences = useRef(new Map<UiLocale, HTMLButtonElement>());

  function selectLocale(locale: UiLocale, focus = false) {
    onChange(locale);
    if (focus) {
      choiceReferences.current.get(locale)?.focus();
    }
  }

  function chooseFromKeyboard(event: KeyboardEvent<HTMLButtonElement>, currentLocale: UiLocale) {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      selectLocale(currentLocale);
      return;
    }

    const currentIndex = choices.findIndex((choice) => choice.value === currentLocale);
    const targetIndex = event.key === "Home"
      ? 0
      : event.key === "End"
        ? choices.length - 1
        : event.key === "ArrowLeft" || event.key === "ArrowUp"
          ? (currentIndex - 1 + choices.length) % choices.length
          : event.key === "ArrowRight" || event.key === "ArrowDown"
            ? (currentIndex + 1) % choices.length
            : undefined;

    if (targetIndex !== undefined) {
      event.preventDefault();
      selectLocale(choices[targetIndex].value, true);
    }
  }

  return (
    <div aria-label={label} className="oac-ui-language-control" role="radiogroup">
      {choices.map((choice) => (
        <button
          aria-checked={choice.value === value}
          className="oac-ui-language-control__choice"
          key={choice.value}
          onClick={() => selectLocale(choice.value)}
          onKeyDown={(event) => chooseFromKeyboard(event, choice.value)}
          ref={(element) => {
            if (element === null) choiceReferences.current.delete(choice.value);
            else choiceReferences.current.set(choice.value, element);
          }}
          role="radio"
          tabIndex={choice.value === value ? 0 : -1}
          type="button"
        >
          {choice.label}
        </button>
      ))}
    </div>
  );
}
"}]}

