{"content":[{"type":"text","text":"import { afterEach, describe, expect, it } from "vitest";

import {
  assertConsoleLocaleCompleteness,
  consoleI18n,
  consoleNamespaces,
  formatConsoleCpuUsage,
  formatConsoleCurrency,
  formatConsoleDateTime,
  formatConsolePercent,
  formatConsoleRelativeTime,
  formatConsoleTokenCount,
  formatConsoleUnit,
  resolveConsoleLocale,
} from "./i18n";

function setBrowserLanguages(languages: string[], language = languages[0] ?? "en-US") {
  Object.defineProperty(navigator, "languages", { configurable: true, value: languages });
  Object.defineProperty(navigator, "language", { configurable: true, value: language });
}

describe("resolveConsoleLocale", () => {
  afterEach(() => {
    localStorage.clear();
    Reflect.deleteProperty(navigator, "languages");
    Reflect.deleteProperty(navigator, "language");
  });

  it("uses the saved user preference before anonymous storage or the browser", () => {
    localStorage.setItem("oac.console.locale", "en-US");
    setBrowserLanguages(["en-US"]);

    expect(resolveConsoleLocale("zh-CN")).toBe("zh-CN");
  });

  it("uses anonymous storage before the browser preference", () => {
    localStorage.setItem("oac.console.locale", "zh-CN");
    setBrowserLanguages(["en-US"]);

    expect(resolveConsoleLocale()).toBe("zh-CN");
  });

  it("uses a supported browser preference and falls back to English", () => {
    setBrowserLanguages(["zh-TW"]);
    expect(resolveConsoleLocale()).toBe("zh-CN");

    setBrowserLanguages(["fr-FR"]);
    expect(resolveConsoleLocale()).toBe("en-US");
  });

  it("keeps product wording in populated, named namespaces", () => {
    for (const namespace of consoleNamespaces) {
      expect(Object.keys(consoleI18n.getResourceBundle("en-US", namespace))).not.toHaveLength(0);
    }

    expect(consoleI18n.exists("overview", { ns: "navigation" })).toBe(true);
    expect(consoleI18n.getResourceBundle("en-US", "common").overview).toBeUndefined();
  });

  it("formats dates, relative time, percentages, money, token counts, CPU usage, and units for the selected locale", () => {
    expect(formatConsoleDateTime(new Date("2026-07-30T12:00:00Z"), "en-US", "UTC")).toContain("2026");
    expect(formatConsoleRelativeTime(-1, "day", "zh-CN")).toContain("昨天");
    expect(formatConsolePercent(0.25, "en-US")).toBe("25%");
    expect(formatConsoleCurrency(12.5, "USD", "en-US")).toBe("$12.50");
    expect(formatConsoleTokenCount(1_200, "en-US")).toMatch(/1.2K/);
    expect(formatConsoleCpuUsage(0.5, "en-US")).toBe("50%");
    expect(formatConsoleUnit(4, "gigabyte", "en-US")).toMatch(/4\s?GB/);
  });

  it("rejects missing locale keys, interpolation mismatches, and invalid plural forms before runtime", () => {
    expect(() => assertConsoleLocaleCompleteness({
      "en-US": { common: { greeting: "Hello {{name}}" } },
      "zh-CN": { common: { greeting: "你好" } },
    })).toThrow(/interpolation/i);

    expect(() => assertConsoleLocaleCompleteness({
      "en-US": { common: { item_one: "{{count}} item" } },
      "zh-CN": { common: { item_other: "{{count}} 项" } },
    })).toThrow(/plural/i);
  });
});
"}]}

