export type ConsoleUiTheme = "light" | "dark";

export type ConsoleUiTokenSet = {
  action: string;
  attention: string;
  canvas: string;
  danger: string;
  focusRing: string;
  info: string;
  ink: string;
  inkMuted: string;
  inkSecondary: string;
  review: string;
  success: string;
  surface: string;
};

// Authoritative values from docs/design/frontend/DESIGN.md front-matter `colors:`.
// The Console foundation (apps/console/src/foundations/oac.css) exposes the same
// values as --oac-color-* CSS variables. This module is a generated-style export
// of that single authority; the regression test in tokens.test.ts verifies every
// value against DESIGN.md so the two can never diverge.
export const consoleUiTokens: Record<ConsoleUiTheme, ConsoleUiTokenSet> = {
  light: {
    action: "#006EDB",
    attention: "#A7500A",
    canvas: "#F5F5F7",
    danger: "#B4232B",
    focusRing: "#006EDB",
    info: "#006C82",
    ink: "#1D1D1F",
    inkMuted: "#767981",
    inkSecondary: "#5E6066",
    review: "#5C4BB0",
    success: "#18734A",
    surface: "#FFFFFF",
  },
  // DESIGN.md only defines dark variants for action, canvas, ink, inkSecondary,
  // and surface; every other semantic keeps its light value in dark mode.
  dark: {
    action: "#6DB1FF",
    attention: "#A7500A",
    canvas: "#111214",
    danger: "#B4232B",
    focusRing: "#006EDB",
    info: "#006C82",
    ink: "#F5F5F7",
    inkMuted: "#767981",
    inkSecondary: "#B8BAC0",
    review: "#5C4BB0",
    success: "#18734A",
    surface: "#1A1C1F",
  },
};

/*
 * Reusable Console UI foundation styles.
 *
 * Colors consume the authoritative OAC design tokens declared in
 * docs/design/frontend/DESIGN.md and exposed by the Console foundation
 * (apps/console/src/foundations/oac.css) as --oac-color-* variables. This
 * stylesheet defines those same variables with the same values so the package
 * is self-contained; tokens.test.ts verifies every value against DESIGN.md so
 * the palette can never diverge from the authority.
 */

:root {
  --oac-color-primary: #006EDB;
  --oac-color-white: #FFFFFF;
  --oac-color-canvas: #F5F5F7;
  --oac-color-surface: #FFFFFF;
  --oac-color-surface-subtle: #F0F1F3;
  --oac-color-surface-raised: #FAFAFB;
  --oac-color-ink: #1D1D1F;
  --oac-color-ink-secondary: #5E6066;
  --oac-color-ink-muted: #767981;
  --oac-color-divider: #D9DADE;
  --oac-color-action: #006EDB;
  --oac-color-action-hover: #0058B5;
  --oac-color-action-subtle: #E8F2FF;
  --oac-color-success: #18734A;
  --oac-color-success-subtle: #E9F7EF;
  --oac-color-attention: #A7500A;
  --oac-color-attention-subtle: #FFF1E5;
  --oac-color-danger: #B4232B;
  --oac-color-danger-subtle: #FDECEF;
  --oac-color-review: #5C4BB0;
  --oac-color-review-subtle: #F0EDFF;
  --oac-color-info: #006C82;
  --oac-color-info-subtle: #E6F6F8;
  --oac-color-focus: #006EDB;
  --oac-color-canvas-dark: #111214;
  --oac-color-surface-dark: #1A1C1F;
  --oac-color-surface-raised-dark: #23262A;
  --oac-color-ink-dark: #F5F5F7;
  --oac-color-ink-secondary-dark: #B8BAC0;
  --oac-color-divider-dark: #373A40;
  --oac-color-action-dark: #6DB1FF;

  color: var(--oac-color-ink);
  background: var(--oac-color-canvas);
  font-family: ui-sans-serif, system-ui, sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root {
    --oac-color-canvas: var(--oac-color-canvas-dark);
    --oac-color-surface: var(--oac-color-surface-dark);
    --oac-color-surface-raised: var(--oac-color-surface-raised-dark);
    --oac-color-ink: var(--oac-color-ink-dark);
    --oac-color-ink-secondary: var(--oac-color-ink-secondary-dark);
    --oac-color-divider: var(--oac-color-divider-dark);
    --oac-color-action: var(--oac-color-action-dark);
  }
}

/* ---- Shared primitive chrome ---- */

.oac-ui-button,
.oac-ui-input,
.oac-ui-language-control__choice {
  border: 1px solid transparent;
  border-radius: 8px;
  font: inherit;
}

.oac-ui-button,
.oac-ui-language-control__choice {
  min-height: 44px;
  padding: 8px 12px;
}

/* ---- Button: default, hover, pressed, focus, disabled, loading ---- */

.oac-ui-button--action { background: var(--oac-color-action); color: var(--oac-color-white); }
.oac-ui-button--danger { background: var(--oac-color-danger); color: var(--oac-color-white); }
.oac-ui-button--quiet { background: transparent; color: var(--oac-color-action); }

.oac-ui-button:not(:disabled):hover {
  background: var(--oac-color-action-hover);
}
.oac-ui-button--danger:not(:disabled):hover { background: var(--oac-color-danger); filter: brightness(0.92); }
.oac-ui-button--quiet:not(:disabled):hover { background: var(--oac-color-action-subtle); }

.oac-ui-button:not(:disabled):active {
  transform: scale(0.97);
}
.oac-ui-button--quiet:not(:disabled):active { color: var(--oac-color-action-hover); }

/* Loading retains the original button label while signaling busy state. */
.oac-ui-button[aria-busy="true"] {
  cursor: progress;
  opacity: 0.75;
}
.oac-ui-button:disabled { cursor: not-allowed; opacity: 0.65; }

/* ---- TextInput: default, hover, focus, disabled, invalid ---- */

.oac-ui-field { display: grid; gap: 4px; max-width: 720px; }
.oac-ui-field__label { font-weight: 600; }
.oac-ui-input { background: var(--oac-color-surface); color: var(--oac-color-ink); min-height: 44px; padding: 8px 12px; }

.oac-ui-input:not(:disabled):hover { border-color: var(--oac-color-action); }
.oac-ui-input:disabled { cursor: not-allowed; opacity: 0.65; }
.oac-ui-input[aria-invalid="true"] { border-color: var(--oac-color-danger); }

/* ---- Language radiogroup: default, hover, pressed, checked, focus ---- */

.oac-ui-language-control { display: inline-flex; border: 1px solid var(--oac-color-ink-muted); border-radius: 8px; }
.oac-ui-language-control__choice { background: transparent; color: var(--oac-color-ink); }
.oac-ui-language-control__choice:not(:disabled):hover { background: var(--oac-color-action-subtle); }
.oac-ui-language-control__choice:not(:disabled):active { background: var(--oac-color-action-subtle); transform: scale(0.97); }
.oac-ui-language-control__choice[aria-checked="true"] { background: var(--oac-color-action); color: var(--oac-color-white); }

/* ---- Shared focus and pattern surfaces ---- */

.oac-ui-button:focus-visible,
.oac-ui-input:focus-visible,
.oac-ui-language-control__choice:focus-visible { outline: 3px solid var(--oac-color-focus); outline-offset: 2px; }

.oac-ui-state-summary,
.oac-ui-evidence-block,
.oac-ui-command-feedback { background: var(--oac-color-surface); border: 1px solid var(--oac-color-ink-muted); border-radius: 12px; padding: 16px; }
.oac-ui-evidence-block dl { display: grid; gap: 8px; margin: 0; }
.oac-ui-evidence-block dl div { display: grid; gap: 2px; }
.oac-ui-evidence-block dt { color: var(--oac-color-ink-secondary); font-weight: 600; }
.oac-ui-evidence-block dd { margin: 0; }

import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";

import { consoleUiTokens } from "./tokens";

const design = readFileSync(resolve(process.cwd(), "../../docs/design/frontend/DESIGN.md"), "utf8");
const css = readFileSync(resolve(process.cwd(), "src/styles.css"), "utf8");

// Every semantic the UI foundation exports, mapped to its DESIGN.md color name.
const lightColors = {
  action: "action",
  attention: "attention",
  canvas: "canvas",
  danger: "danger",
  focusRing: "focus",
  info: "info",
  ink: "ink",
  inkMuted: "inkMuted",
  inkSecondary: "inkSecondary",
  review: "review",
  success: "success",
  surface: "surface",
} as const;

// DESIGN.md defines dark variants only for these semantics; every other
// semantic keeps its light value in dark mode.
const darkColorVariants: Partial<Record<keyof typeof lightColors, string>> = {
  action: "actionDark",
  canvas: "canvasDark",
  ink: "inkDark",
  inkSecondary: "inkSecondaryDark",
  surface: "surfaceDark",
};

function designColor(name: string): string {
  const value = design.match(new RegExp(`^  ${name}: "(#[0-9A-F]{6})"`, "m"))?.[1];
  expect(value, `${name} must exist in DESIGN.md`).toBeDefined();
  return value as string;
}

function kebabCase(value: string) {
  return value.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);
}

describe("Console UI foundation tokens", () => {
  it("exports the DESIGN.md light palette as its single authority", () => {
    for (const [token, designName] of Object.entries(lightColors)) {
      expect(consoleUiTokens.light[token as keyof typeof lightColors], token).toBe(designColor(designName));
    }
  });

  it("uses the DESIGN.md dark variants where declared and keeps light values otherwise", () => {
    for (const token of Object.keys(lightColors) as Array<keyof typeof lightColors>) {
      const darkVariant = darkColorVariants[token];
      expect(consoleUiTokens.dark[token], `${token} dark`).toBe(
        darkVariant === undefined ? designColor(lightColors[token]) : designColor(darkVariant),
      );
    }
  });

  it("declares the authoritative color CSS variables in the shared stylesheet", () => {
    for (const [token, designName] of Object.entries(lightColors)) {
      expect(css).toContain(`--oac-color-${kebabCase(designName)}: ${designColor(designName)};`);
    }
  });
});

