describe("LanguageSegmentedControl", () => {
  it("offers named keyboard-operable language choices without flags", () => {
    const onChange = vi.fn();
    render(<LanguageSegmentedControl value="en-US" onChange={onChange} />);

    const chinese = screen.getByRole("radio", { name: "中文" });
    expect(screen.getByRole("radiogroup", { name: "Language" })).toBeVisible();
    expect(chinese).toHaveAttribute("aria-checked", "false");

    fireEvent.keyDown(chinese, { key: "Enter" });
    expect(onChange).toHaveBeenCalledWith("zh-CN");

    fireEvent.keyDown(chinese, { key: "ArrowRight" });
    expect(onChange).toHaveBeenLastCalledWith("en-US");
    expect(screen.getByRole("radio", { name: "English" })).toHaveAttribute("tabindex", "0");

    fireEvent.keyDown(chinese, { key: "End" });
    expect(onChange).toHaveBeenLastCalledWith("en-US");
  });

  it("wraps arrow navigation and honours Home and Space with the roving tab stop", () => {
    const onChange = vi.fn();
    render(<LanguageSegmentedControl value="zh-CN" onChange={onChange} />);

    const chinese = screen.getByRole("radio", { name: "中文" });
    const english = screen.getByRole("radio", { name: "English" });
    expect(chinese).toHaveAttribute("tabindex", "0");
    expect(english).toHaveAttribute("tabindex", "-1");

    fireEvent.keyDown(english, { key: "ArrowLeft" });
    expect(onChange).toHaveBeenLastCalledWith("zh-CN");
    expect(chinese).toHaveAttribute("tabindex", "0");

    fireEvent.keyDown(chinese, { key: "ArrowUp" });
    expect(onChange).toHaveBeenLastCalledWith("en-US");

    fireEvent.keyDown(english, { key: "Home" });
    expect(onChange).toHaveBeenLastCalledWith("zh-CN");
    expect(chinese).toHaveFocus();

    fireEvent.keyDown(chinese, { key: " " });
    expect(onChange).toHaveBeenLastCalledWith("zh-CN");
  });
});

