it("keeps product wording in populated, named namespaces", () => {
  for (const namespace of consoleNamespaces) {
    expect(Object.keys(consoleI18n.getResourceBundle("en-US", namespace))).not.toHaveLength(0);
  }

  expect(consoleI18n.exists("overview", { ns: "navigation" })).toBe(true);
  expect(consoleI18n.getResourceBundle("en-US", "common").overview).toBeUndefined();
});

it("registers exactly the declared namespace set without a cross-feature fallback", () => {
  expect(consoleI18n.options.ns).toEqual(consoleNamespaces);
  expect(consoleI18n.options.defaultNS).toBe("common");
  // Only the explicitly declared common namespace is a fallback target; feature
  // namespaces must not resolve each other's messages (DESIGN.md namespace isolation).
  expect(consoleI18n.options.fallbackNS).toEqual(["common"]);
});

it("keeps unrelated-namespace lookups as visible misses", () => {
  // `overview` exists only in `navigation`; a `settings` lookup must not resolve it.
  expect(consoleI18n.exists("overview", { ns: "settings" })).toBe(false);
  expect(consoleI18n.t("overview", { ns: "settings" })).toBe("overview");
});

