  // Locale is a display preference. This delivery constrains persistence to the
  // anonymous local preference (DESIGN.md localization ownership): there is no
  // published Platform API write contract for an authenticated account locale,
  // so we do not invent one. Applying the selection synchronously from local
  // storage removes the stale-completion race entirely.
  persistAnonymousConsoleLocale(nextLocale);
  setLocale(nextLocale);
};

