import { cleanup, fireEvent, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { consoleI18n } from "../i18n/i18n";
import { ConsoleApplication } from "./ConsoleApplication";

const authenticatedSession = {
  kind: "authenticated" as const,
  context: {
    attentionCount: 0,
    locale: "en-US",
    session: {
      kind: "authenticated" as const,
      principalName: "Avery Chen",
      scope: { id: "scope-platform", name: "Platform Engineering" },
    },
  },
};

describe("ConsoleApplication", () => {
  beforeEach(async () => {
    localStorage.clear();
    document.documentElement.lang = "";
    await consoleI18n.changeLanguage("en-US");
  });

  afterEach(() => {
    cleanup();
  });

  it("persists a language selection to the anonymous local preference before applying it", async () => {
    const sessionAdapter = {
      readConsoleSession: vi.fn().mockResolvedValue(authenticatedSession),
    };

    render(<ConsoleApplication sessionAdapter={sessionAdapter} />);

    await screen.findByRole("banner");
    await waitFor(() => expect(document.documentElement.lang).toBe("en-US"));
    fireEvent.click(screen.getByRole("radio", { name: "中文" }));

    await waitFor(() => expect(document.documentElement.lang).toBe("zh-CN"));
    expect(localStorage.getItem("oac.console.locale")).toBe("zh-CN");
  });

  it("applies the latest selection deterministically when switching rapidly", async () => {
    const sessionAdapter = {
      readConsoleSession: vi.fn().mockResolvedValue(authenticatedSession),
    };

    render(<ConsoleApplication sessionAdapter={sessionAdapter} />);

    await screen.findByRole("banner");
    await waitFor(() => expect(document.documentElement.lang).toBe("en-US"));

    fireEvent.click(screen.getByRole("radio", { name: "中文" }));
    fireEvent.click(screen.getByRole("radio", { name: "English" }));

    await waitFor(() => expect(document.documentElement.lang).toBe("en-US"));
    expect(localStorage.getItem("oac.console.locale")).toBe("en-US");
  });

  it("keeps the anonymous local preference when the session cannot be read", async () => {
    const sessionAdapter = {
      readConsoleSession: vi.fn().mockResolvedValue({ kind: "unavailable" }),
    };

    render(<ConsoleApplication sessionAdapter={sessionAdapter} />);

    await screen.findByRole("heading", { name: "Console temporarily unavailable" });
    fireEvent.click(screen.getByRole("radio", { name: "中文" }));

    await waitFor(() => expect(document.documentElement.lang).toBe("zh-CN"));
    expect(localStorage.getItem("oac.console.locale")).toBe("zh-CN");
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";

import { browserSessionAdapter } from "./BrowserSessionAdapter";

describe("browserSessionAdapter", () => {
  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it("treats a 401 response as an anonymous session", async () => {
    vi.stubGlobal("fetch", vi.fn().mockResolvedValue({ ok: false, status: 401 }));

    await expect(browserSessionAdapter.readConsoleSession()).resolves.toEqual({ kind: "anonymous" });
  });

  it.each([
    ["a server failure", () => Promise.resolve({ ok: false, status: 500 })],
    ["a malformed success payload", () => Promise.resolve({ ok: true, status: 200, json: () => Promise.resolve({}) })],
    ["a network failure", () => Promise.reject(new Error("network unavailable"))],
  ])("reports %s as unavailable instead of anonymous", async (_description, request) => {
    vi.stubGlobal("fetch", vi.fn(request));

    await expect(browserSessionAdapter.readConsoleSession()).resolves.toEqual({ kind: "unavailable" });
  });

  it("does not expose a server-side locale write (anonymous local preference only)", () => {
    expect("saveConsoleLocale" in browserSessionAdapter).toBe(false);
  });
});

