import { existsSync, readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "../../../..");

describe("Console consumer clean build", () => {
  it("resolves the workspace @oac/ui dependency from source so no prior UI build is required", () => {
    const viteConfig = readFileSync(resolve(repositoryRoot, "apps/console/vite.config.ts"), "utf8");

    expect(viteConfig).toContain("@oac/ui/styles.css");
    expect(viteConfig).toContain("@oac/ui");
    expect(viteConfig).toContain("packages/ui/src/styles.css");
    expect(viteConfig).toContain("packages/ui/src/index.ts");
  });

  it("does not require @oac/ui dist artifacts for the Console build", () => {
    const uiDistStyles = resolve(repositoryRoot, "packages/ui/dist/styles.css");
    const uiDistIndex = resolve(repositoryRoot, "packages/ui/dist/index.js");

    // The Console build must be self-sufficient: it must not import the UI
    // package's production dist stylesheet/index, which only exist after a
    // separate `@oac/ui build` step. Alias targets are the source files.
    const viteConfig = readFileSync(resolve(repositoryRoot, "apps/console/vite.config.ts"), "utf8");
    expect(viteConfig).not.toContain("packages/ui/dist/styles.css");
    expect(viteConfig).not.toContain("packages/ui/dist/index.js");

    const aliasedStyles = resolve(repositoryRoot, "packages/ui/src/styles.css");
    const aliasedIndex = resolve(repositoryRoot, "packages/ui/src/index.ts");
    expect(existsSync(aliasedStyles)).toBe(true);
    expect(existsSync(aliasedIndex)).toBe(true);
    expect(existsSync(uiDistStyles)).toBe(false);
    expect(existsSync(uiDistIndex)).toBe(false);
  });
});

